": "b837040d-e841-4bb7-8bb0-7dc1ff1b27de", "type": "concept", "title": "greatest happiness principle"}, {"id": "d3523a6a-454d-40e1-8935-1b4c46ef7abf", "type": "concept", "title": "hedonic calculus"}, {"id": "8619dcb9-7033-4227-aa7e-3d0eb4146084", "type": "concept", "title": "higher pleasures"}, {"id": "87fc6c34-14d8-41ab-888f-e6ce643123fd", "type": "concept", "title": "impartiality"}, {"id": "ebfc09b6-c64f-4037-8c51-93f40492f822", "type": "concept", "title": "aggregation"}, {"id": "befec6e2-1858-471e-91a6-f2a0deef364f", "type": "concept", "title": "maximization"}], "description": "Students learn the structure of Bentham and Mill's moral theory."}, {"id": "17957943-be0e-46b0-ada5-38023133d7c5", "type": "subtopic", "title": "Act, rule, and preference consequentialism", "children": [{"id": "088e101e-e80b-42a5-9589-e3937589d0df", "type": "concept", "title": "Specific terms and topics:"}, {"id": "89007a9c-1d40-4e2e-b376-0a5856b94efe", "type": "concept", "title": "act utilitarianism"}, {"id": "d79d1eff-2809-4c4b-acda-b895e65a722f", "type": "concept", "title": "rule utilitarianism"}, {"id": "591fa7aa-020f-4f1b-ae84-d4c224c6d702", "type": "concept", "title": "preference satisfaction"}, {"id": "c28099ff-5dd8-4194-81d8-8de68a5d791b", "type": "concept", "title": "expected utility"}, {"id": "abf4a0a2-e7f2-4634-a57f-66c241a50640", "type": "concept", "title": "actual consequence"}, {"id": "a4c5cd6d-5f7a-4f8d-aeed-6055281c6878", "type": "concept", "title": "foreseeable consequence"}, {"id": "91d2ef4a-15e7-4b10-95c9-758a51c8dfa6", "type": "concept", "title": "decision procedure"}, {"id": "d3b43918-e1e7-48b1-9039-622a4c2c8e84", "type": "concept", "title": "criterion of rightness"}, {"id": "978eb479-060b-4ebe-b092-3704e2910521", "type": "concept", "title": "utility monster"}, {"id": "e7a63a98-9f23-4a8a-a8e7-ccd5895c7c48", "type": "concept", "title": "demandingness"}], "description": "Students compare versions of consequentialism and what each tries to fix."}, {"id": "a6b53499-5bd6-48